import bisect
from fractions import Fraction


class RunningStats:
    def __init__(self):
        self._data = []
        self._sum = Fraction(0)
        self._float = False

    @staticmethod
    def _check(x):
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            raise TypeError("x must be an int or float")

    def add(self, x):
        self._check(x)
        bisect.insort(self._data, x)
        self._sum += Fraction(x)

    def remove(self, x):
        i = bisect.bisect_left(self._data, x)
        if i >= len(self._data) or self._data[i] != x:
            raise KeyError(x)
        del self._data[i]
        self._sum -= Fraction(x)

    def __len__(self):
        return len(self._data)

    def count(self, x):
        return bisect.bisect_right(self._data, x) - bisect.bisect_left(self._data, x)

    def total(self):
        if any(isinstance(v, float) for v in self._data):
            return float(self._sum)
        return int(self._sum) if self._sum.denominator == 1 else float(self._sum)

    def mean(self):
        if not self._data:
            raise ValueError("empty")
        return float(self._sum / len(self._data))

    def median(self):
        n = len(self._data)
        if n == 0:
            raise ValueError("empty")
        if n % 2:
            return self._data[n // 2]
        return (self._data[n // 2 - 1] + self._data[n // 2]) / 2

    def quantile(self, q):
        if not 0.0 <= q <= 1.0:
            raise ValueError("q must be in [0, 1]")
        n = len(self._data)
        if n == 0:
            raise ValueError("empty")
        pos = q * (n - 1)
        lo = int(pos)
        frac = pos - lo
        if lo + 1 >= n:
            return self._data[-1]
        if frac == 0:
            return self._data[lo]
        return self._data[lo] + (self._data[lo + 1] - self._data[lo]) * frac

    def rank(self, x):
        return bisect.bisect_left(self._data, x)
